CREATE TABLE loyalty_wallets(account_id text PRIMARY KEY REFERENCES organization_customers,points integer NOT NULL DEFAULT 0 CHECK(points>=0));
CREATE TABLE organization_loyalty_transactions(id text PRIMARY KEY,account_id text NOT NULL REFERENCES organization_customers,restaurant_id text NOT NULL REFERENCES restaurants,points integer NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE loyalty_wallets ENABLE ROW LEVEL SECURITY;
CREATE POLICY wallet_scope ON loyalty_wallets USING(EXISTS(SELECT 1 FROM organization_customers c WHERE c.id=loyalty_wallets.account_id AND (c.subject=app.user_id() OR app.org_member(c.organization_id)))) WITH CHECK(EXISTS(SELECT 1 FROM organization_customers c WHERE c.id=loyalty_wallets.account_id AND (c.subject=app.user_id() OR app.org_member(c.organization_id))));
ALTER TABLE organization_loyalty_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY wallet_history ON organization_loyalty_transactions USING(app.in_restaurant(restaurant_id));
CREATE FUNCTION app.customer_points(cid text) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT CASE WHEN o.loyalty_scope='organization' AND c.account_id IS NOT NULL THEN coalesce(w.points,0) ELSE c.points END FROM customers c JOIN restaurants r ON r.id=c.restaurant_id JOIN organizations o ON o.id=r.organization_id LEFT JOIN loyalty_wallets w ON w.account_id=c.account_id WHERE c.id=cid AND app.in_restaurant(c.restaurant_id) $$;
CREATE FUNCTION app.loyalty_delta() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE delta integer; shared boolean; BEGIN
 IF NEW.account_id IS NULL OR NEW.points=OLD.points THEN RETURN NEW; END IF;
 SELECT o.loyalty_scope='organization' INTO shared FROM restaurants r JOIN organizations o ON o.id=r.organization_id WHERE r.id=NEW.restaurant_id;
 IF NOT shared THEN RETURN NEW; END IF;
 delta:=NEW.points-OLD.points;
 INSERT INTO loyalty_wallets(account_id,points) VALUES(NEW.account_id,0) ON CONFLICT DO NOTHING;
 UPDATE loyalty_wallets SET points=points+delta WHERE account_id=NEW.account_id RETURNING points INTO NEW.points;
 INSERT INTO organization_loyalty_transactions VALUES(gen_random_uuid()::text,NEW.account_id,NEW.restaurant_id,delta,'Mouvement de fidélité établissement',now());
 RETURN NEW; END $$;
CREATE TRIGGER shared_loyalty BEFORE UPDATE OF points ON customers FOR EACH ROW EXECUTE FUNCTION app.loyalty_delta();
CREATE FUNCTION app.restaurant_admin(rid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT app.org_admin(r.organization_id) OR EXISTS(SELECT 1 FROM memberships m JOIN profiles p ON p.id=m.profile_id WHERE m.restaurant_id=r.id AND m.profile_id=app.user_id() AND m.role='OWNER' AND p.status='active') FROM restaurants r WHERE r.id=rid $$;
DROP POLICY scoped_read ON invitations;
DROP POLICY scoped_insert ON invitations;
DROP POLICY scoped_update ON invitations;
DROP POLICY scoped_delete ON invitations;
CREATE POLICY invitation_read ON invitations FOR SELECT USING(app.restaurant_admin(restaurant_id));
CREATE POLICY invitation_insert ON invitations FOR INSERT WITH CHECK(app.restaurant_admin(restaurant_id));
CREATE POLICY invitation_update ON invitations FOR UPDATE USING(app.restaurant_admin(restaurant_id)) WITH CHECK(app.restaurant_admin(restaurant_id));
CREATE POLICY invitation_delete ON invitations FOR DELETE USING(app.restaurant_admin(restaurant_id));
DROP POLICY scoped_insert ON memberships;
DROP POLICY scoped_update ON memberships;
DROP POLICY scoped_delete ON memberships;
CREATE POLICY membership_insert ON memberships FOR INSERT WITH CHECK(app.restaurant_admin(restaurant_id));
CREATE POLICY membership_update ON memberships FOR UPDATE USING(app.restaurant_admin(restaurant_id)) WITH CHECK(app.restaurant_admin(restaurant_id));
CREATE POLICY membership_delete ON memberships FOR DELETE USING(app.restaurant_admin(restaurant_id));
REVOKE ALL ON FUNCTION app.customer_points(text),app.restaurant_admin(text),app.loyalty_delta() FROM PUBLIC;
